// Manual commission deductions use settlement snapshots so the same advance is never deducted twice.
let advanceContext=null;
function initAdvances(){state.advances??=[];for(const r of Object.values(state.records)){if(r.commissionPaid&&!r.settlement&&!Array.isArray(r.commissionPayments))r.settlement={gross:cents(r.commission),deductions:[],net:cents(r.commission),date:null};}}
function commissionPayments(r){return Array.isArray(r?.commissionPayments)?r.commissionPayments:[];}
function advanceUsed(id){return Object.values(state.records).reduce((sum,r)=>sum+[...(r.settlement?[r.settlement]:[]),...commissionPayments(r)].reduce((n,p)=>n+(p.deductions||[]).filter(d=>d.id===id).reduce((x,d)=>x+d.amount,0),0),0);}
function commissionSummary(person=selected,month=$('#month').value){initAdvances();const r=state.records[month+':'+person],gross=cents(r?.commission||0);if(r?.settlement){const s=r.settlement;return {...s,discount:s.deductions.reduce((n,d)=>n+d.amount,0),paid:s.net,remaining:0,closed:true};}const payments=commissionPayments(r),paidGross=payments.reduce((n,p)=>n+p.gross,0),discount=payments.reduce((n,p)=>n+p.deductions.reduce((x,d)=>x+d.amount,0),0),paid=payments.reduce((n,p)=>n+p.net,0),remaining=Math.max(0,gross-paidGross);return {gross,deductions:payments.flatMap(p=>p.deductions),discount,net:remaining,paid,remaining,closed:remaining===0&&gross>0,payments};}
function selectedAdvanceDeductions(gross){let total=0;const deductions=[];for(const checkbox of document.querySelectorAll('[data-advance-deduction]')){if(!checkbox.checked)continue;const id=checkbox.dataset.advanceDeduction,a=state.advances.find(a=>a.id===id),input=document.querySelector('[data-advance-amount="'+id+'"]'),remaining=a?Math.max(0,a.amount-advanceUsed(a.id)):0,amount=input?parseCredit(input.value):0;if(!a||a.voided||amount<=0||amount>remaining){toast('Confira o valor informado para o vale selecionado.');return null;}total+=amount;deductions.push({id:a.id,amount,description:a.description});}if(total>gross){toast('Os descontos não podem ultrapassar o valor da comissão.');return null;}return deductions;}
function personSaleShare(s,person=selected){return saleShares(s).find(([id])=>id===person)?.[1]||0;}
function saleBorderoPaid(r,saleId){return commissionPayments(r).reduce((n,p)=>n+(p.salePayments||[]).filter(x=>x.saleId===saleId).reduce((a,x)=>a+x.amount,0),0);}
function borderoSales(){const r=record();return monthlySales().filter(s=>!s.voided&&(s.originator===selected||s.closer===selected)).map(s=>({...s,share:personSaleShare(s),paid:saleBorderoPaid(r,s.id)})).filter(s=>s.share>s.paid);}
function borderoAdvanceRows(){return state.advances.filter(a=>a.person===selected&&!a.voided&&a.amount>advanceUsed(a.id)).sort((a,b)=>a.date.localeCompare(b.date)||a.id.localeCompare(b.id)).map(a=>{const remaining=a.amount-advanceUsed(a.id);return `<label class="advance-deduction-row"><input type="checkbox" data-advance-deduction="${esc(a.id)}"><span><strong>${esc(a.description)}</strong><small>Saldo do vale: ${money(remaining/100)}</small></span><input type="text" inputmode="decimal" data-money data-money-min="0.01" data-money-max="${remaining/100}" data-advance-amount="${esc(a.id)}" value="${formatCredit(remaining)}" aria-label="Valor a descontar de ${esc(a.description)}"></label>`;}).join('');}
function openBordero(){const sales=borderoSales(),person=state.people.find(p=>p.id===selected);if(!sales.length){toast('Não há comissão de venda pendente para criar um borderô.');return;}$('#bordero-reference').textContent=person.name+' · '+$('#month').value.split('-').reverse().join('/');$('#bordero-sales').innerHTML=sales.map(s=>{const remaining=s.share-s.paid;return `<label class="bordero-sale-row"><input type="checkbox" data-bordero-sale="${esc(s.id)}"><span><strong>${esc(s.client)}</strong><small>${esc(s.date.split('-').reverse().join('/'))} · ${SALE_TABLES[s.table]} · disponível ${money(remaining/100)}</small></span><input type="text" inputmode="decimal" data-money data-money-min="0.01" data-money-max="${remaining/100}" data-bordero-amount="${esc(s.id)}" value="${formatCredit(remaining)}" aria-label="Valor da comissão de ${esc(s.client)}"></label>`;}).join('');const advances=borderoAdvanceRows();$('#bordero-advances').innerHTML=advances?`<h3>Vales para descontar</h3><p class="hint">Marque somente os vales que entrarão neste pagamento.</p>${advances}`:'<p class="hint">Nenhum vale pendente para descontar.</p>';$('#bordero-total').textContent=money(0);$('#bordero-dialog').showModal();}
function borderoSelection(){const r=record(),sales=[];let gross=0;for(const checkbox of document.querySelectorAll('[data-bordero-sale]')){if(!checkbox.checked)continue;const sale=state.saleEntries.find(s=>s.id===checkbox.dataset.borderoSale),amount=parseCredit(document.querySelector('[data-bordero-amount="'+checkbox.dataset.borderoSale+'"]')?.value||'');if(!sale)return null;const available=personSaleShare(sale)-saleBorderoPaid(r,sale.id);if(amount<=0||amount>available){toast('Confira o valor informado para cada venda selecionada.');return null;}sales.push({saleId:sale.id,client:sale.client,date:sale.date,amount});gross+=amount;}if(!sales.length){toast('Selecione pelo menos uma venda.');return null;}const deductions=selectedAdvanceDeductions(gross);if(!deductions)return null;return {sales,gross,deductions,discount:deductions.reduce((n,d)=>n+d.amount,0)};}
function printBordero(p){const person=state.people.find(x=>x.id===selected),month=$('#month').value.split('-').reverse().join('/'),rows=p.salePayments.map(s=>`<tr><td>${esc(s.date.split('-').reverse().join('/'))}</td><td>${esc(s.client)}</td><td>${money(s.amount/100)}</td></tr>`).join(''),discounts=p.deductions.length?p.deductions.map(d=>`<tr><td colspan="2">${esc(d.description)}</td><td>- ${money(d.amount/100)}</td></tr>`).join(''):'<tr><td colspan="3">Nenhum desconto</td></tr>',w=window.open('','_blank');if(!w){toast('Permita pop-ups para gerar o PDF do borderô.');return;}w.document.write(`<!doctype html><html><head><meta charset="utf-8"><title>Borderô - ${esc(person.name)}</title><style>body{font:14px Arial;color:#211c13;margin:36px}header{border-bottom:3px solid #bd963b;padding-bottom:18px;margin-bottom:24px}h1{margin:0 0 8px}small{color:#766b59}table{width:100%;border-collapse:collapse;margin:16px 0 26px}th,td{padding:10px;border-bottom:1px solid #ddd;text-align:left}th:last-child,td:last-child{text-align:right}.totals{margin-left:auto;width:320px}.totals div{display:flex;justify-content:space-between;padding:8px}.net{font-size:18px;font-weight:bold;background:#211c13;color:#f1d9a8}.sign{margin-top:70px;border-top:1px solid #333;padding-top:8px;width:320px}@media print{button{display:none}}</style></head><body><header><h1>Borderô de comissões</h1><small>Seven Gold · ${esc(person.name)} · ${month} · ${esc(p.date.split('-').reverse().join('/'))}</small></header><h2>Comissões pagas</h2><table><thead><tr><th>Data</th><th>Cliente</th><th>Valor pago</th></tr></thead><tbody>${rows}</tbody></table><h2>Descontos</h2><table><tbody>${discounts}</tbody></table><div class="totals"><div><span>Comissões</span><strong>${money(p.gross/100)}</strong></div><div><span>Descontos</span><strong>- ${money((p.gross-p.net)/100)}</strong></div><div class="net"><span>Líquido pago</span><strong>${money(p.net/100)}</strong></div></div><div class="sign">Assinatura do recebedor</div><script>window.onload=()=>setTimeout(()=>window.print(),150)<\/script></body></html>`);w.document.close();}
function printBordero(p){const person=state.people.find(x=>x.id===selected),month=$('#month').value.split('-').reverse().join('/'),date=esc(p.date.split('-').reverse().join('/')),rows=p.salePayments.map(s=>`<tr><td>${esc(s.date.split('-').reverse().join('/'))}</td><td>${esc(s.client)}</td><td>${money(s.amount/100)}</td></tr>`).join(''),discounts=p.deductions.length?p.deductions.map(d=>`<tr><td colspan="2">${esc(d.description)}</td><td>- ${money(d.amount/100)}</td></tr>`).join(''):'<tr><td colspan="3">Nenhum desconto</td></tr>',w=window.open('','_blank');if(!w){toast('Permita pop-ups para gerar o PDF do borderô.');return;}w.document.write(`<!doctype html><html><head><meta charset="utf-8"><title>Borderô - ${esc(person.name)}</title><style>body{font:14px Arial;color:#211c13;margin:36px}header{border-bottom:3px solid #bd963b;padding-bottom:18px;margin-bottom:24px}h1{margin:0 0 8px}small{color:#766b59}table{width:100%;border-collapse:collapse;margin:16px 0 26px}th,td{padding:10px;border-bottom:1px solid #ddd;text-align:left}th:last-child,td:last-child{text-align:right}.totals{margin-left:auto;width:320px}.totals div{display:flex;justify-content:space-between;padding:8px}.net{font-size:18px;font-weight:bold;background:#211c13;color:#f1d9a8}.receipt{margin-top:72px;text-align:center;break-inside:avoid}.receipt p{text-align:left;margin-bottom:58px}.signature-line{width:420px;max-width:90%;margin:0 auto;border-top:1px solid #222;padding-top:9px;font-weight:bold}.signature-name{margin-top:6px;color:#666}@media print{button{display:none}}</style></head><body><header><h1>Borderô de comissões</h1><small>Seven Gold · ${esc(person.name)} · ${month} · ${date}</small></header><h2>Comissões pagas</h2><table><thead><tr><th>Data</th><th>Cliente</th><th>Valor pago</th></tr></thead><tbody>${rows}</tbody></table><h2>Descontos</h2><table><tbody>${discounts}</tbody></table><div class="totals"><div><span>Comissões</span><strong>${money(p.gross/100)}</strong></div><div><span>Descontos</span><strong>- ${money((p.gross-p.net)/100)}</strong></div><div class="net"><span>Líquido pago</span><strong>${money(p.net/100)}</strong></div></div><section class="receipt"><p>Declaro que recebi o pagamento líquido indicado neste borderô.</p><div class="signature-line">Assinatura do vendedor</div><div class="signature-name">${esc(person.name)} · Data: ____/____/________</div></section><script>window.onload=()=>setTimeout(()=>window.print(),150)<\/script></body></html>`);w.document.close();}
function createBordero(){const data=borderoSelection();if(!data)return;const net=data.gross-data.discount;if(!confirm('Criar borderô com pagamento líquido de '+money(net/100)+'?'))return;const p={id:crypto.randomUUID(),date:new Intl.DateTimeFormat('sv-SE',{timeZone:'America/Sao_Paulo',year:'numeric',month:'2-digit',day:'2-digit'}).format(new Date()),gross:data.gross,net,deductions:data.deductions,salePayments:data.sales};const r=record();(r.commissionPayments??=[]).push(p);r.commissionPaid=commissionSummary().remaining===0;save();$('#bordero-dialog').close();render();printBordero(p);toast('Borderô criado e pronto para salvar em PDF');}
function commissionPanel(){const s=commissionSummary(),payments=commissionPayments(record());return `<div class="commission-breakdown"><div><small>Comissão bruta</small><strong>${money(s.gross/100)}</strong></div><div><small>Vales descontados</small><strong>− ${money(s.discount/100)}</strong></div><div><small>Comissão ainda disponível</small><strong>${money(s.remaining/100)}</strong></div><div><small>Já pago em comissão</small><strong>${money(s.paid/100)}</strong></div></div><div class="week-top"><div><h3>Borderôs do mês</h3><p class="hint">Escolha as vendas e os valores somente ao criar um borderô.</p></div><button class="primary" id="open-bordero" ${!borderoSales().length?'disabled':''}>＋ Criar borderô</button></div>${payments.length?`<div class="bordero-history">${payments.map((p,i)=>`<div><span><strong>Borderô ${i+1}</strong><small>${esc(p.date.split('-').reverse().join('/'))} · líquido ${money(p.net/100)}</small></span><button data-print-bordero="${esc(p.id)}">Gerar PDF</button><button data-delete-bordero="${esc(p.id)}">Estornar</button></div>`).join('')}</div>`:'<p class="hint">Nenhum borderô criado neste mês.</p>'}${record().settlement?'<p class="hint">Existe uma quitação anterior registrada neste mês.</p>':''}`;}
function advancesView(){initAdvances();const list=state.advances.filter(a=>a.person===selected).sort((a,b)=>b.date.localeCompare(a.date));const outstanding=list.filter(a=>!a.voided).reduce((n,a)=>n+Math.max(0,a.amount-advanceUsed(a.id)),0);return `<div class="section-head" style="padding:0"><div><h3>Vales e adiantamentos</h3><p class="hint">Celular, aluguel, empréstimos e outros valores a descontar manualmente na comissão.</p></div><button class="primary" id="add-advance">＋ Registrar vale</button></div><div class="balance-summary"><div>Saldo total de vales a descontar<strong>${money(outstanding/100)}</strong></div></div><p class="hint">Na hora de quitar uma comissão, escolha quais vales serão descontados e informe o valor. Descontos parciais reduzem automaticamente o saldo restante.</p>${list.length?`<div class="advance-card-grid">${list.map(a=>{const used=advanceUsed(a.id),remaining=Math.max(0,a.amount-used),status=a.voided?'Cancelado':remaining===0?'Descontado integralmente':used?'Desconto parcial':'Pendente';return `<article class="advance-card ${a.voided?'voided':''}"><div class="advance-card-head"><strong>${esc(a.description)}</strong><span>${esc(status)}</span></div><div class="advance-card-balance"><small>Saldo restante</small><strong>${money(a.voided?0:remaining/100)}</strong></div><div class="advance-card-meta"><span>Pago em <b>${esc(a.date.split('-').reverse().join('/'))}</b></span><span>Valor original <b>${money(a.amount/100)}</b></span><span>Já descontado <b>${money(used/100)}</b></span></div><div class="advance-card-actions">${used?'<small>Vinculado a comissão quitada</small>':`<button data-edit-advance="${esc(a.id)}">Editar</button><button data-void-advance="${esc(a.id)}">${a.voided?'Restaurar':'Cancelar'}</button>`}</div></article>`;}).join('')}</div>`:'<div class="empty"><h3>Nenhum vale registrado</h3><p>Registre o valor e a data do que você adiantou à pessoa.</p></div>'}`;}
function openAdvance(id=null){initAdvances();const a=state.advances.find(a=>a.id===id);if(a&&advanceUsed(id)){toast('Reabra a comissão vinculada antes de alterar este vale.');return;}const f=$('#advance-form');f.reset();f.elements.person.innerHTML=state.people.map(p=>`<option value="${esc(p.id)}">${esc(p.name)} · ${esc(p.role||'Prestador')}</option>`).join('');f.elements.person.value=a?.person||selected;advanceContext={id,person:selected};$('#advance-title').textContent=a?'Editar vale':'Registrar vale';f.elements.description.value=a?.description||'';f.elements.amount.value=a?formatCredit(a.amount):'';f.elements.date.value=a?.date||new Intl.DateTimeFormat('sv-SE',{timeZone:'America/Sao_Paulo',year:'numeric',month:'2-digit',day:'2-digit'}).format(new Date());$('#advance-dialog').showModal();}
function validateAdvances(s){if(s.advances!==undefined){if(!Array.isArray(s.advances))throw Error('Vales inválidos');const ids=new Set();for(const a of s.advances){if(!a||typeof a.id!=='string'||ids.has(a.id)||!s.people.some(p=>p.id===a.person)||!validDate(a.date)||(a.month!==undefined&&!/^\d{4}-(0[1-9]|1[0-2])$/.test(a.month))||!Number.isSafeInteger(a.amount)||a.amount<=0||typeof a.description!=='string'||!a.description.trim()||typeof a.voided!=='boolean')throw Error('Vale inválido');ids.add(a.id);}}const used={};for(const [key,r] of Object.entries(s.records)){const payments=[...(r.settlement?[r.settlement]:[]),...(r.commissionPayments||[])];if(r.commissionPayments!==undefined&&!Array.isArray(r.commissionPayments))throw Error('Borderôs inválidos');const paymentIds=new Set();for(const x of payments){if(!Number.isSafeInteger(x.gross)||x.gross<0||!Number.isSafeInteger(x.net)||x.net<0||!Array.isArray(x.deductions)||!(x.date===null||validDate(x.date)))throw Error('Quitação inválida');if(x.id&&(typeof x.id!=='string'||paymentIds.has(x.id)))throw Error('Borderô duplicado');if(x.id)paymentIds.add(x.id);if(x.salePayments&&(!Array.isArray(x.salePayments)||!x.salePayments.length||x.salePayments.some(p=>typeof p.saleId!=='string'||typeof p.client!=='string'||!validDate(p.date)||!Number.isSafeInteger(p.amount)||p.amount<=0)||x.salePayments.reduce((n,p)=>n+p.amount,0)!==x.gross))throw Error('Vendas do borderô inválidas');let total=0;for(const d of x.deductions){const a=(s.advances||[]).find(a=>a.id===d.id);if(!a||a.person!==key.slice(8)||a.voided||!Number.isSafeInteger(d.amount)||d.amount<=0||typeof d.description!=='string')throw Error('Desconto inválido');used[d.id]=(used[d.id]||0)+d.amount;if(used[d.id]>a.amount)throw Error('Desconto duplicado');total+=d.amount;}if(x.gross-total!==x.net)throw Error('Total inválido');}}}
if(typeof document.createElement==='function'){const borderoDialog=document.createElement('dialog');borderoDialog.id='bordero-dialog';borderoDialog.innerHTML='<form id="bordero-form"><div class="section-head"><div><h2>Criar borderô</h2><p id="bordero-reference" class="hint"></p></div><button type="button" id="close-bordero" aria-label="Fechar borderô">✕</button></div><h3>Vendas que serão pagas</h3><p class="hint">Marque a venda e mantenha o valor total ou digite quanto deseja pagar agora.</p><div id="bordero-sales"></div><section class="advance-deduction-picker" id="bordero-advances"></section><div class="bordero-total"><span>Valor líquido do pagamento</span><strong id="bordero-total">R$ 0,00</strong></div><button type="submit" class="primary">Criar borderô e gerar PDF</button></form>';document.body.append(borderoDialog);}
document.querySelector('#close-advance').onclick=()=>$('#advance-dialog').close();
document.querySelector('#advance-form').onsubmit=e=>{e.preventDefault();const f=e.target;if(!f.reportValidity()||!advanceContext)return;const a={id:advanceContext.id||crypto.randomUUID(),person:f.elements.person.value,description:f.elements.description.value.trim(),amount:parseCredit(f.elements.amount.value),date:f.elements.date.value,voided:false};if(!state.people.some(p=>p.id===a.person)||!a.description||!validDate(a.date)||!a.amount)return;const prior=state.advances.find(x=>x.id===a.id);if(prior&&advanceUsed(a.id)){toast('Este vale já foi descontado em uma comissão quitada.');return;}if(prior){Object.assign(prior,a);delete prior.month;}else state.advances.push(a);selected=a.person;tab='advances';save();render();$('#advance-dialog').close();toast('Vale registrado');};
document.querySelector('#close-bordero').onclick=()=>$('#bordero-dialog').close();
document.querySelector('#bordero-form').onsubmit=e=>{e.preventDefault();createBordero();};
document.addEventListener('change',e=>{if(e.target.matches('[data-bordero-sale],[data-advance-deduction],[data-bordero-amount],[data-advance-amount]')){const data=borderoSelectionPreview();$('#bordero-total').textContent=money(data/100);}});
function borderoSelectionPreview(){let gross=0,discount=0;document.querySelectorAll('[data-bordero-sale]:checked').forEach(c=>gross+=parseCredit(document.querySelector('[data-bordero-amount="'+c.dataset.borderoSale+'"]')?.value||'')||0);document.querySelectorAll('[data-advance-deduction]:checked').forEach(c=>discount+=parseCredit(document.querySelector('[data-advance-amount="'+c.dataset.advanceDeduction+'"]')?.value||'')||0);return Math.max(0,gross-discount);}
document.addEventListener('click',e=>{const b=e.target.closest('button');if(!b)return;if(b.id==='add-advance')openAdvance();if(b.id==='open-bordero')openBordero();if(b.dataset.printBordero){const p=commissionPayments(record()).find(x=>x.id===b.dataset.printBordero);if(p)printBordero(p);}if(b.dataset.deleteBordero){const r=record(),p=commissionPayments(r).find(x=>x.id===b.dataset.deleteBordero);if(p&&confirm('Estornar este borderô? As comissões e os vales voltarão a ficar disponíveis.')){r.commissionPayments=r.commissionPayments.filter(x=>x.id!==p.id);r.commissionPaid=false;save();render();toast('Borderô estornado');}}if(b.dataset.editAdvance)openAdvance(b.dataset.editAdvance);if(b.dataset.voidAdvance){const a=state.advances.find(a=>a.id===b.dataset.voidAdvance);if(!a||advanceUsed(a.id))return;a.voided=!a.voided;save();render();}});
const legacyAdvanceMonth=document.querySelector('#advance-form [name="month"]');if(typeof legacyAdvanceMonth?.closest==='function'){legacyAdvanceMonth.closest('label')?.remove();const note=document.querySelector('#advance-form .hint');if(note)note.textContent='O vale ficará pendente até você escolher o valor do desconto ao quitar uma comissão.';}
